def strip_leading_prose(text: str) -> str:
    pattern = r'^\s*(?:#.*|from\s+.*|import\s+.*|class\s+.*|def\s+.*|as\s+|raise\s+|return\s+|yield\s+|assert\s+|break\s+|continue\s+|del\s+|global\s+|nonlocal\s+|pass\s+|print\s+|try\s+|except\s+|finally\s+|async\s+|await\s+)'
    cleaned_text = re.sub(pattern, '', text, count=1)
    return cleaned_text.strip()

